import type { BadgeProps } from "./badge.types";

import { forwardRef } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";

import { BadgeClasses, StyledBadge } from "./badge.styles";

const Badge = forwardRef(
  (
    { className, variant = "default", type, children, ...props }: BadgeProps,
    ref: React.ForwardedRef<HTMLDivElement>,
  ) => {
    const theme = useTheme();
    const typeClassName =
      type &&
      BadgeClasses[type.replace(/-(\w)/g, (_, c) => c.toUpperCase()) as keyof typeof BadgeClasses];
    const rootClasses = clsx(BadgeClasses.root, typeClassName, className);

    return (
      <StyledBadge
        ref={ref}
        className={rootClasses}
        currentTheme={theme}
        variant={variant}
        {...props}
      >
        {type?.includes("dot") ? null : children}
      </StyledBadge>
    );
  },
);

Badge.displayName = "Badge";

export default Badge;
